package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsOwnerFood {
 @GameTest(template="empty") public static void ownFoodDrawIsActualInventoryAndNeverRevenue(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=f.t.state.businesses.values().stream().filter(v->v.kind.equals("procurement")).findFirst().orElseThrow();var family=f.r.state.families.get(f.r.state.people.get(b.owner).family);for(var stock:f.r.stocks(family.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}var home=new FamilyLivelihood.Home();home.processor=b.owner;f.t.state.households.put(family.id,home);b.stock[0].add(10,1000);b.stock[0].freshness.groups.getFirst().age=FoodAge.SCALE/2;long money=f.t.money(f.s),grain=f.t.grain(f.s),income=b.lastIncome;int n=OwnerFood.draw(f.s,family);h.assertTrue(n==8&&b.stock[0].count==2&&RuralRules.count(f.r.stocks(family.id),false)==8,"Owner uses only needed actual local food");h.assertTrue(f.t.money(f.s)==money&&f.t.grain(f.s)==grain&&b.sales==0&&b.lastIncome==income&&b.foodDrawCostCents==800,"Withdrawal is neither production, revenue nor cash grant");h.assertTrue(f.r.stocks(family.id).getFirst().ages[0].groups.getFirst().age==FoodAge.SCALE/2,"Taking food does not renew freshness");}h.succeed();}
 @GameTest(template="empty") public static void foodOnTheRoadCannotTeleportIntoTheOwnersPantry(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=f.t.state.businesses.values().stream().filter(v->v.kind.equals("procurement")).findFirst().orElseThrow();var family=f.r.state.families.get(f.r.state.people.get(b.owner).family);for(var stock:f.r.stocks(family.id)){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}var home=new FamilyLivelihood.Home();home.processor=b.owner;f.t.state.households.put(family.id,home);b.cargo[0].add(20,2000);b.phase=1;h.assertTrue(OwnerFood.draw(f.s,family)==0&&b.cargo[0].count==20,"Transport remains unavailable until returned and unloaded");}h.succeed();}
 @GameTest(template="empty") public static void warehouseLimitIncludesCargoAndPerGoodTransport(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var b=f.t.state.businesses.values().stream().filter(v->v.kind.equals("procurement")).findFirst().orElseThrow();b.stock[0].add(950,0);b.cargo[2].add(40,0);long money=f.t.money(f.s),grain=f.t.grain(f.s);int n=CityRoute.buyCityGrain(f.s,b,100);h.assertTrue(n==10&&CityRoute.room(f.s,b)==0,"1000-unit level-one warehouse includes the forty units in transit");h.assertTrue(f.t.money(f.s)==money&&f.t.grain(f.s)==grain,"Capacity checks do not invent or discard cash or grain");}h.succeed();}
}
